from collections import defaultdict, deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  color=grid[r][c]
  if color==9 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); pts=[]
  while q:
   x,y=q.pop(); pts.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    a,b=x+dx,y+dy
    if 0<=a<R and 0<=b<C and grid[a][b]==color and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
  minr=min(x for x,y in pts); minc=min(y for x,y in pts)
  shp=tuple(sorted((x-minr,y-minc) for x,y in pts))
  comps.append((color,len(pts),(minr,minc,max(x for x,y in pts),max(y for x,y in pts)),shp))
for i,(col,n,bbox,shp) in enumerate(comps): print(i,col,n,bbox,shp if n<10 else '')

for i,(col,n,bbox,shp) in enumerate(comps):
 if n>=5:
  h=bbox[2]-bbox[0]+1; w=bbox[3]-bbox[1]+1
  print(i,col,n, h,w)
  for r in range(h): print(''.join('#' if (r,c) in shp else '.' for c in range(w)))

def norm(sh):
 mr=min(r for r,c in sh); mc=min(c for r,c in sh); return frozenset((r-mr,c-mc) for r,c in sh)
def transforms(sh):
 res=[]
 for flip in [1,-1]:
  for rot in range(4):
   p=[]
   for r,c in sh:
    x,y=r, c*flip
    for _ in range(rot): x,y=y,-x
    p.append((x,y))
   res.append(norm(p))
 return res
for i in range(len(comps)):
 for j in range(i+1,len(comps)):
  if any(comps[i][3]==t for t in transforms(comps[j][3])):
   print(i,comps[i][0],comps[i][1],comps[i][2],'<=>',j,comps[j][0],comps[j][1],comps[j][2])

